"""Random string pairs for the edit distance.

Note what the "a few edits apart" case does *not* claim. Applying three edits
to a word tells you the distance is at most three; it may be less, because two
edits can undo each other. The description says at most, and the reference
solution settles what it actually is.
"""

LETTERS = "abcdefghijklmnopqrstuvwxyz"


def generate(rng, count):
    builders = (_a_few_edits, _identical, _one_empty, _unrelated)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, a, b, description=""):
    return {"name": name, "stdin": "%s\n%s\n" % (a, b),
            "description": description}


def _word(rng, length=None):
    length = length if length is not None else rng.randint(4, 9)
    return "".join(rng.choice(LETTERS) for _ in range(length))


def _a_few_edits(rng, index):
    original = _word(rng)
    edited = original
    edits = rng.randint(1, 3)
    for _ in range(edits):
        choice = rng.randrange(3)
        where = rng.randrange(len(edited) + 1)
        if choice == 0 or not edited:
            edited = edited[:where] + rng.choice(LETTERS) + edited[where:]
        elif choice == 1:
            where = min(where, len(edited) - 1)
            edited = edited[:where] + edited[where + 1:]
        else:
            where = min(where, len(edited) - 1)
            edited = (edited[:where] + rng.choice(LETTERS)
                      + edited[where + 1:])
    return _case("a few edits apart #%d" % index, original, edited,
                 "The second string was built from the first with %d edit(s), "
                 "so the answer is at most %d -- edits can cancel out."
                 % (edits, edits))


def _identical(rng, index):
    word = _word(rng)
    return _case("the same string twice #%d" % index, word, word)


def _one_empty(rng, index):
    word = _word(rng)
    empty_first = rng.random() < 0.5
    return _case("one side empty #%d" % index,
                 "" if empty_first else word, word if empty_first else "",
                 "Every character has to be inserted, or every one deleted.")


def _unrelated(rng, index):
    return _case("unrelated words #%d" % index,
                 _word(rng, rng.randint(3, 8)), _word(rng, rng.randint(3, 8)))
